        "std::optional<long long> MajoritySummaryVerify::majority(const std::vector<std::vector<long long>>& shards){struct State{long long candidate;std::size_t residual;};std::vector<State> partials;std::size_t total=0;for(const auto&s:shards){State p{0,0};for(long long v:s){if(p.residual==0){p={v,1};}else if(v==p.candidate)++p.residual;else --p.residual;}partials.push_back(p);total+=s.size();}State merged{0,0};for(auto p:partials){if(merged.residual==0)merged=p;else if(p.residual==0)continue;else if(merged.candidate==p.candidate)merged.residual+=p.residual;else if(merged.residual>=p.residual)merged.residual-=p.residual;else{merged.candidate=p.candidate;merged.residual=p.residual-merged.residual;}}if(total==0||merged.residual==0)return std::nullopt;std::size_t count=0;for(const auto&s:shards)count+=static_cast<std::size_t>(std::count(s.begin(),s.end(),merged.candidate));return count>total/2?std::optional<long long>(merged.candidate):std::nullopt;}",
