        "std::optional<CrossShardInversions::Result> CrossShardInversions::count(const std::vector<std::vector<long long>>& shards){auto merge=[](Result a,Result b)->std::optional<Result>{Result out{a.inversions+b.inversions,{}};if(out.inversions<a.inversions)return std::nullopt;std::size_t i=0,j=0;while(i<a.sorted.size()||j<b.sorted.size()){if(j==b.sorted.size()||(i<a.sorted.size()&&a.sorted[i]<=b.sorted[j]))out.sorted.push_back(a.sorted[i++]);else{unsigned long long add=a.sorted.size()-i;if(out.inversions>ULLONG_MAX-add)return std::nullopt;out.inversions+=add;out.sorted.push_back(b.sorted[j++]);}}return out;};std::vector<Result> parts;for(const auto&s:shards){Result p{0,s};for(std::size_t i=0;i<s.size();++i)for(std::size_t j=i+1;j<s.size();++j)if(s[i]>s[j])++p.inversions;std::sort(p.sorted.begin(),p.sorted.end());parts.push_back(p);}while(parts.size()>1){std::vector<Result> next;for(std::size_t i=0;i<parts.size();i+=2){if(i+1==parts.size())next.push_back(parts[i]);else{auto m=merge(parts[i],parts[i+1]);if(!m)return std::nullopt;next.push_back(*m);}}parts=next;}return parts.empty()?Result{0,{}}:parts[0];}",
