        "std::vector<ConvexHullFragments::Point> ConvexHullFragments::reduce(const std::vector<std::vector<Point>>& shards){for(const auto&s:shards)for(auto p:s)if(p.x<-1000000000LL||p.x>1000000000LL||p.y<-1000000000LL||p.y>1000000000LL)return {};auto hull=[](std::vector<Point> p){std::sort(p.begin(),p.end());p.erase(std::unique(p.begin(),p.end(),[](auto a,auto b){return a==b;}),p.end());if(p.size()<3)return p;auto cross=[](Point a,Point b,Point c)->long long{long long dx1,dy1,dx2,dy2,p1,p2,cr; if(__builtin_sub_overflow(b.x,a.x,&dx1)||__builtin_sub_overflow(c.y,a.y,&dy1)||__builtin_sub_overflow(b.y,a.y,&dy2)||__builtin_sub_overflow(c.x,a.x,&dx2)||__builtin_mul_overflow(dx1,dy1,&p1)||__builtin_mul_overflow(dx2,dy2,&p2)||__builtin_sub_overflow(p1,p2,&cr))return 1;return cr;};std::vector<Point> h;for(auto x:p){while(h.size()>=2&&cross(h[h.size()-2],h.back(),x)<=0)h.pop_back();h.push_back(x);}std::size_t lower=h.size();for(std::size_t i=p.size()-1;i-->0;){auto x=p[i];while(h.size()>lower&&cross(h[h.size()-2],h.back(),x)<=0)h.pop_back();h.push_back(x);}h.pop_back();return h;};std::vector<Point> candidates;for(auto s:shards){auto h=hull(s);candidates.insert(candidates.end(),h.begin(),h.end());}return hull(candidates);}",
