        "std::optional<std::vector<PriorityReservoirMerge::Sample>> PriorityReservoirMerge::reduce(const std::vector<std::vector<Item>>& shards,unsigned long long seed,std::size_t k){auto mix=[](unsigned long long x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);};auto less=[](const Sample&a,const Sample&b){return std::tie(a.priority,a.id)<std::tie(b.priority,b.id);};std::set<unsigned long long> ids;std::vector<std::vector<Sample>> partials;for(const auto&s:shards){std::vector<Sample> p;for(auto x:s){if(!ids.insert(x.id).second)return std::nullopt;p.push_back({mix(seed^x.id),x.id,x.payload});}std::sort(p.begin(),p.end(),less);if(p.size()>k)p.resize(k);partials.push_back(p);}std::vector<Sample> out;for(auto&p:partials){out.insert(out.end(),p.begin(),p.end());std::sort(out.begin(),out.end(),less);if(out.size()>k)out.resize(k);}return out;}",
